/* firebase-enrollment.js */
/** Private number/name matching and atomic one-number/one-account enrollment. */
window.createNumberEnrollment = ({ db, sdk }) => {
  const ref = (collection, id) => sdk.doc(db, collection, id);
  const emailOf = user => user.email.trim().toLowerCase();
  const mismatch = () => ({ code: "enrollment/mismatch" });

  async function prepare(user, number, name) {
    const no = StudentNumbers.normalize(number);
    const key = StudentNumbers.nameKey(name);
    if (!no || !key) throw mismatch();
    const existing = await sdk.getDocFromServer(ref("applications", user.uid));
    if (existing.exists()) {
      if (existing.data().status === "rejected") throw { code: "enrollment/rejected" };
      return;
    }
    try {
      await sdk.setDoc(ref("registrationRequests", user.uid), { no, nameKey: key, email: emailOf(user) });
    } catch (error) {
      if (error.code === "permission-denied") {
        await sdk.setDoc(ref("applications", user.uid), { no, name: name.trim().replace(/\s+/g, " "), nameKey: key,
          email: emailOf(user), status: "pending", createdAt: sdk.serverTimestamp() });
        return;
      }
      throw error;
    }
  }

  async function complete(user, number, name) {
    const application = await sdk.getDocFromServer(ref("applications", user.uid));
    if (application.exists()) {
      if (application.data().status === "rejected") throw { code: "enrollment/rejected" };
      return;
    }
    if ((await sdk.getDocFromServer(ref("enrollments", user.uid))).exists()) return;
    if (number || name) {
      await prepare(user, number, name);
      if ((await sdk.getDocFromServer(ref("applications", user.uid))).exists()) return;
    }
    const request = await sdk.getDocFromServer(ref("registrationRequests", user.uid));
    if (!request.exists()) return;
    const data = request.data();
    const batch = sdk.writeBatch(db);
    batch.set(ref("numberClaims", data.no), { uid: user.uid });
    batch.set(ref("enrollments", user.uid), { no: data.no, nameKey: data.nameKey, email: emailOf(user) });
    try { await batch.commit(); }
    catch (error) {
      if (error.code === "permission-denied") throw mismatch();
      throw error;
    }
  }

  function watchExisting(user, onData, onError) {
    let stopNumber = () => {};
    let closed = false;
    const stopEnrollment = sdk.onSnapshot(ref("enrollments", user.uid), { includeMetadataChanges: true }, snapshot => {
      stopNumber();
      if (snapshot.metadata.fromCache) { onData(null); return; }
      if (!snapshot.exists()) {
        stopNumber = sdk.onSnapshot(ref("students", emailOf(user)), { includeMetadataChanges: true }, legacy => {
          if (!closed) onData(!legacy.metadata.fromCache && legacy.exists() ? legacy.data() : null);
        }, onError);
        return;
      }
      const enrollment = snapshot.data();
      stopNumber = sdk.onSnapshot(ref("studentNumbers", enrollment.no), { includeMetadataChanges: true }, roster => {
        if (closed) return;
        const student = !roster.metadata.fromCache && roster.exists() ? roster.data() : null;
        onData(student ? { ...student, email: emailOf(user) } : null);
      }, onError);
    }, onError);
    return () => { closed = true; stopNumber(); stopEnrollment(); };
  }

  function watch(user, onData, onError) {
    let stopExisting = () => {};
    const stopApplication = sdk.onSnapshot(ref("applications", user.uid), { includeMetadataChanges: true }, snapshot => {
      stopExisting();
      if (snapshot.metadata.fromCache) { onData(null); return; }
      if (!snapshot.exists()) { stopExisting = watchExisting(user, onData, onError); return; }
      const application = snapshot.data();
      if (application.status === "rejected") { onData(null); return; }
      const profile = { no: application.approvedNo || application.no, name: application.approvedName || application.name,
        email: emailOf(user), enabled: true, approvalStatus: application.status, accessKey: user.uid };
      if (application.status === "pending") { onData(profile); return; }
      if (application.status !== "approved") { onData(null); return; }
      stopExisting = sdk.onSnapshot(ref("studentNumbers", profile.no), { includeMetadataChanges: true }, roster => {
        onData(!roster.metadata.fromCache && roster.exists() && roster.data().enabled === true ? profile : null);
      }, onError);
    }, onError);
    return () => { stopApplication(); stopExisting(); };
  }

  function watchRoster(onData, onError) {
    let numbers = [], emails = [], numbersReady = false, emailsReady = false;
    const emit = () => { if (numbersReady && emailsReady) onData([...numbers, ...emails]); };
    const stopNumbers = sdk.onSnapshot(sdk.collection(db, "studentNumbers"), { includeMetadataChanges: true }, snapshot => {
      if (snapshot.metadata.fromCache) return;
      numbers = snapshot.docs.map(document => document.data()); numbersReady = true; emit();
    }, onError);
    const stopEmails = sdk.onSnapshot(sdk.collection(db, "students"), { includeMetadataChanges: true }, snapshot => {
      if (snapshot.metadata.fromCache) return;
      emails = snapshot.docs.map(document => document.data()); emailsReady = true; emit();
    }, onError);
    return () => { stopNumbers(); stopEmails(); };
  }

  async function reset(no) {
    const claim = await sdk.getDocFromServer(ref("numberClaims", no));
    if (!claim.exists()) return;
    const batch = sdk.writeBatch(db);
    const uid = claim.data().uid;
    batch.delete(ref("numberClaims", no));
    batch.delete(ref("enrollments", uid));
    batch.delete(ref("registrationRequests", uid));
    await batch.commit();
  }

  return { prepare, complete, watch, watchRoster, reset };
};
;

/* approval-client.js */
/** Sends a review decision with the current administrator's Firebase ID token. */
window.createApprovalClient = auth => async (uid, action, no, name) => {
  const base = window.MEE101_APPROVAL_URL;
  if (!base || !auth.currentUser) throw { code: "approval/unavailable" };
  const target = new URL(base);
  const local = ["127.0.0.1", "localhost"].includes(location.hostname);
  if (target.protocol !== "https:" && !(local && target.hostname === "127.0.0.1")) throw { code: "approval/unavailable" };
  const token = await auth.currentUser.getIdToken(true);
  const response = await fetch(new URL("review", target.href.endsWith("/") ? target : `${target.href}/`), {
    method: "POST", credentials: "omit", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ uid, action, ...(no ? { no } : {}), ...(name ? { name } : {}) })
  });
  const data = await response.json();
  if (!response.ok || !data.ok) throw { code: "approval/failed", publicMessage: data.error || "İşlem tamamlanamadı." };
  return data;
};
;

/* firebase-adapter.js */
/** Official browser SDK handles password exchange and session-token refresh. */
window.createFirebaseStudentAdapter = async config => {
  const SDK = "https://www.gstatic.com/firebasejs/13.1.0";
  const [appSdk, authSdk, dbSdk] = await Promise.all([
    import(`${SDK}/firebase-app.js`), import(`${SDK}/firebase-auth.js`), import(`${SDK}/firebase-firestore.js`)
  ]);
  const app = appSdk.initializeApp(config, "mee101-students");
  const auth = authSdk.getAuth(app);
  const db = dbSdk.initializeFirestore(app, { localCache: dbSdk.memoryLocalCache() });
  if (window.MEE101_FIREBASE_EMULATORS && ["127.0.0.1", "localhost"].includes(location.hostname)) {
    authSdk.connectAuthEmulator(auth, "http://127.0.0.1:9099", { disableWarnings: true });
    dbSdk.connectFirestoreEmulator(db, "127.0.0.1", 8088);
  }
  await authSdk.setPersistence(auth, authSdk.browserSessionPersistence);
  const reference = email => dbSdk.doc(db, "students", email);
  const enrollment = createNumberEnrollment({ db, sdk: dbSdk });
  return {
    getUser: () => auth.currentUser,
    async signInInstructor(token) {
      const { user } = await authSdk.signInWithCustomToken(auth, token);
      const registered = (await dbSdk.getDocFromServer(dbSdk.doc(db, "admins", user.uid))).exists();
      if (!user.emailVerified || !registered) {
        await authSdk.signOut(auth);
        throw { code: "permission-denied" };
      }
    },
    async start(onUser) {
      authSdk.onAuthStateChanged(auth, onUser);
      await auth.authStateReady();
    },
    async isAdmin(uid) { return (await dbSdk.getDocFromServer(dbSdk.doc(db, "admins", uid))).exists(); },
    watchRoster: enrollment.watchRoster,
    watchApplications(onData, onError) {
      return dbSdk.onSnapshot(dbSdk.collection(db, "applications"), { includeMetadataChanges: true }, snapshot => {
        if (!snapshot.metadata.fromCache) onData(snapshot.docs.map(document => ({ ...document.data(), uid: document.id })));
      }, onError);
    },
    reviewApplication: createApprovalClient(auth),
    watchStudent(email, onData, onError) {
      return enrollment.watch(auth.currentUser, onData, onError);
    },
    async signIn(email, password, number, name) {
      const { user } = await authSdk.signInWithEmailAndPassword(auth, email, password);
      if (!user.emailVerified) throw { code: "auth/unverified-email" };
      const isAdmin = (await dbSdk.getDocFromServer(dbSdk.doc(db, "admins", user.uid))).exists();
      if (!isAdmin) await enrollment.complete(user, number, name);
    },
    async register(email, password, number, name) {
      let user, created = false;
      try {
        ({ user } = await authSdk.createUserWithEmailAndPassword(auth, email, password));
        created = true;
      } catch (error) {
        if (error.code !== "auth/email-already-in-use") throw error;
        ({ user } = await authSdk.signInWithEmailAndPassword(auth, email, password));
      }
      try { await enrollment.prepare(user, number, name); }
      catch (error) {
        if (created) { try { await authSdk.deleteUser(user); } catch { /* No enrollment or course permission was granted. */ } }
        await authSdk.signOut(auth);
        throw error;
      }
      await authSdk.sendEmailVerification(user, { url: new URL("./", location.href).href });
      await authSdk.signOut(auth);
    },
    async resetPassword(email) { await authSdk.sendPasswordResetEmail(auth, email); },
    async resendVerification() {
      if (!auth.currentUser) throw { code: "auth/sign-in-required" };
      await authSdk.sendEmailVerification(auth.currentUser, { url: new URL("./", location.href).href });
    },
    async writeRoster(students, removals) {
      const batch = dbSdk.writeBatch(db);
      const rosterRef = student => student.email ? reference(student.email) : dbSdk.doc(db, "studentNumbers", student.no);
      students.forEach(student => batch.set(rosterRef(student), student));
      removals.forEach(student => batch.delete(rosterRef(student)));
      await batch.commit();
    },
    resetNumber: enrollment.reset,
    signOut: () => authSdk.signOut(auth),
    errorMessage(error) {
      const messages = {
        "enrollment/mismatch": "Öğrenci numarası ve ad-soyad eşleşmedi, kayıt kapalı veya numara başka bir hesaba bağlı. Bilgilerinizi kontrol edin; gerekirse öğretim üyesine başvurun.",
        "enrollment/rejected": "Başvurunuz yönetici tarafından reddedildi. Erişiminiz kapatıldı.",
        "approval/unavailable": "Onay hizmeti henüz hazır değil veya yönetici oturumu kapalı.",
        "auth/unverified-email": "Önce e-postanızdaki doğrulama bağlantısını açınız; ardından tekrar giriş yapınız.",
        "auth/sign-in-required": "Önce e-posta ve parolanızla giriş yapmayı deneyiniz; ardından doğrulamayı yeniden gönderiniz.",
        "auth/email-already-in-use": "Hesap oluşturulamadı. Mevcut hesabınızla giriş yapın veya parolanızı sıfırlayın.",
        "auth/too-many-requests": "Çok fazla deneme yapıldı. Bir süre sonra tekrar deneyiniz.",
        "auth/weak-password": "Daha güçlü bir parola belirleyiniz.",
        "auth/network-request-failed": "Bağlantı kurulamadı. İnternet bağlantınızı kontrol ediniz.",
        "permission-denied": "Bu işlem için yetkiniz yok. Yönetici kaydınızı kontrol ediniz."
      };
      return (error.code === "approval/failed" && error.publicMessage) || messages[error.code] || "İşlem tamamlanamadı. E-posta, parola ve Firebase yapılandırmasını kontrol ediniz.";
    }
  };
};
;

/* firebase-students.js */
/** Connects the private access service to the existing compact portal controls. */
window.FirebaseStudents = (() => {
  let service;
  let ready;
  const status = () => document.getElementById("roster-sync-status");
  const report = text => { status().textContent = text; };
  const unavailable = () => ({ ok: false, error: "Firebase bağlantısı henüz yapılandırılmadı. Öğretim üyesine başvurunuz." });

  async function initialize(onChange) {
    if (ready) return ready;
    ready = (async () => {
      if (!window.MEE101_FIREBASE_CONFIG) { report(unavailable().error); return; }
      try {
        const adapter = await createFirebaseStudentAdapter(window.MEE101_FIREBASE_CONFIG);
        service = new FirebaseStudentService(adapter, state => {
          report(state.isAdmin ? "Öğretim üyesi oturumu · Gizli öğrenci listesi bağlantısı etkin." : "Öğrencileri yönetmek için öğretim üyesi girişi yapınız.");
          onChange(state);
        });
        await service.start();
      } catch { report("Firebase bağlantısı kurulamadı. Öğrenci erişimi kapalı; mevcut yerel veriler korundu."); }
    })();
    return ready;
  }

  async function signIn(email, password, number, name) {
    await ready;
    if (!service) return unavailable();
    const result = await service.signIn(email, password, number, name);
    if (!result.ok) return result;
    const deadline = Date.now() + 10000;
    while (!service.accessResolved && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 50));
    if (service.profile || service.isAdmin) return { ok: true };
    await service.signOut();
    return { ok: false, error: "Bu hesap için etkin ders kaydı bulunamadı veya kayıt doğrulanamadı. Öğretim üyesine başvurunuz." };
  }

  async function saveText(text, replaceAll) {
    const result = StudentRosterImport.parse(text);
    if (!result.ok) return result;
    if (!service) return unavailable();
    return service.saveRoster(result.students, replaceAll);
  }

  return {
    initialize, signIn, saveText,
    signInInstructor: async token => { await ready; return service ? service.signInInstructor(token) : unavailable(); },
    get profile() { return service?.profile || null; },
    get isAdmin() { return service?.isAdmin === true; },
    get roster() { return service?.isAdmin ? service.roster : []; },
    get applications() { return service?.isAdmin ? service.applications : []; },
    register: async (email, password, number, name) => { await ready; return service ? service.register(email, password, number, name) : unavailable(); },
    resetPassword: async email => { await ready; return service ? service.resetPassword(email) : unavailable(); },
    resendVerification: async () => service ? service.perform(() => service.adapter.resendVerification()) : unavailable(),
    signOut: async () => service ? service.signOut() : { ok: true },
    saveRoster: async students => service ? service.saveRoster(students) : unavailable(),
    removeStudent: async key => service ? service.removeStudent(key) : unavailable(),
    removeStudents: async keys => service ? service.removeStudents(keys) : unavailable(),
    resetNumber: async no => service ? service.resetNumber(no) : unavailable(),
    reviewApplication: async (uid, action, no, name) => service ? service.reviewApplication(uid, action, no, name) : unavailable()
  };
})();
;

/* approval-ui.js */
/** Renders private pending applications only inside the authenticated instructor panel. */
window.renderApprovalApplications = () => {
  const container = document.getElementById("approval-applications");
  if (!container) return;
  container.replaceChildren();
  const applications = FirebaseStudents.applications.filter(application => application.status === "pending"
    || application.status === "rejected" && application.deletionStatus === "pending");
  document.getElementById("approval-pending-count").textContent = applications.length;
  for (const application of applications) {
    const card = document.createElement("article");
    card.className = "approval-card";
    const pending = application.status === "pending";
    card.innerHTML = `<div><strong>${escapeXml(application.name)}</strong> · ${escapeXml(application.email)}</div>
      <small>${pending ? "Eşleşmeyen kayıt · Onay bekliyor · Geçici erişim açık" : "Reddedildi · Erişim kapalı · Hesap silme yeniden denenecek"}</small>
      <div class="approval-fields"><label>Öğrenci Numarası<input data-review-number value="${escapeXml(application.no)}" inputmode="numeric" maxlength="32" /></label>
      <label>Ad Soyad<input data-review-name value="${escapeXml(application.name)}" maxlength="200" /></label></div>
      <div class="firebase-auth-actions">${pending ? '<button class="btn btn-primary" data-review-action="approve">Onayla</button>' : ""}
      <button class="btn approval-reject-button" data-review-action="reject">${pending ? "Reddet ve Hesabı Sil" : "Hesap Silmeyi Tekrar Dene"}</button></div>`;
    card.querySelectorAll("[data-review-action]").forEach(button => {
      button.addEventListener("click", async () => {
        const action = button.dataset.reviewAction;
        if (action === "reject" && !confirm(`${application.email} hesabının erişimi kapatılacak ve giriş hesabı kalıcı olarak silinecek. Devam edilsin mi?`)) return;
        card.querySelectorAll("button").forEach(control => { control.disabled = true; });
        const result = await FirebaseStudents.reviewApplication(application.uid, action,
          card.querySelector("[data-review-number]").value, card.querySelector("[data-review-name]").value);
        const feedback = document.getElementById("approval-feedback");
        feedback.textContent = result.ok ? action === "approve" ? "Kayıt onaylandı."
          : result.deletionStatus === "deleted" ? "Erişim kapatıldı ve giriş hesabı silindi."
          : "Erişim kapatıldı. Hesap silme işlemi otomatik yeniden denenecek." : result.error;
        card.querySelectorAll("button").forEach(control => { control.disabled = false; });
      });
    });
    container.appendChild(card);
  }
};
;

/* instructor-login.js */
(function (root) {
  /** Opens both permissions together and rolls back partial or cancelled sign-ins. */
  class InstructorSession {
    constructor({ publishing, students }) {
      this.publishing = publishing;
      this.students = students;
      this.generation = 0;
      this.busy = false;
    }

    async login({ token, firebaseToken }) {
      if (this.busy) return { ok: false, error: "Önceki giriş tamamlanıyor. Yeniden deneyiniz." };
      this.busy = true;
      const generation = ++this.generation;
      try {
        if (!token || !firebaseToken) throw new Error("Giriş bilgileri eksik. Yeniden deneyiniz.");
        const result = await this.students.signInInstructor(firebaseToken);
        if (!result.ok) throw new Error(result.error);
        if (generation !== this.generation) throw new Error("Giriş iptal edildi.");
        await this.publishing.login(token);
        if (generation !== this.generation) throw new Error("Giriş iptal edildi.");
        if (this.students.isAdmin === false) throw new Error("Öğretim üyesi yetkisi artık etkin değil.");
        return { ok: true };
      } catch (error) {
        await this.logout();
        return { ok: false, error: error.message || "Öğretim üyesi girişi tamamlanamadı." };
      } finally {
        this.busy = false;
      }
    }

    async logout() {
      ++this.generation;
      this.publishing.logout();
      return this.students.signOut();
    }
  }

  /** Accepts login results only from the opened window, configured origin and nonce. */
  function createGitHubSignIn({ host, serviceUrl, onCredentials, onState }) {
    let pending;
    const cancel = () => {
      if (!pending) return;
      host.clearInterval(pending.timer);
      host.removeEventListener("message", pending.receive);
      pending.popup.close();
      pending = null;
      onState(false);
    };
    const start = () => {
      if (pending) return;
      const url = new URL("github/start", serviceUrl);
      const requestId = Array.from(host.crypto.getRandomValues(new Uint8Array(32)), b => b.toString(16).padStart(2, "0")).join("");
      url.searchParams.set("request_id", requestId);
      const popup = host.open(url.href, "lecturenotes-instructor");
      if (!popup) return onState(false, "Giriş penceresi açılamadı. Bu site için açılır pencerelere izin veriniz.");
      const attempt = { popup, processing: false, deadline: Date.now() + 600000 };
      attempt.receive = async event => {
        const data = event.data;
        if (pending !== attempt || attempt.processing || event.origin !== url.origin || event.source !== popup
          || data?.type !== "lecturenotes-github") return;
        if (data.requestId !== requestId && !(data.error && !data.requestId)) return;
        attempt.processing = true;
        if (data.error) { cancel(); return onState(false, data.error); }
        let result;
        try { result = await onCredentials(data); }
        catch { result = { ok: false, error: "Giriş tamamlanamadı. Yeniden deneyiniz." }; }
        if (pending !== attempt) return;
        cancel();
        onState(false, result.ok ? "" : result.error, result.ok);
      };
      attempt.timer = host.setInterval(() => {
        if (attempt.processing) return;
        if (popup.closed || Date.now() > attempt.deadline) {
          cancel();
          onState(false, "Giriş iptal edildi veya süresi doldu. Yeniden deneyebilirsiniz.");
        }
      }, 500);
      pending = attempt;
      host.addEventListener("message", attempt.receive);
      onState(true);
    };
    return { start, cancel, isProcessing: () => pending?.processing === true };
  }

  root.InstructorSession = InstructorSession;
  root.createGitHubSignIn = createGitHubSignIn;
  if (typeof module !== "undefined") module.exports = { InstructorSession, createGitHubSignIn };
})(typeof window !== "undefined" ? window : globalThis);
;

/* roster-table.js */
(function (root) {
  const FIELD_IDS = ["inp-roster-numbers", "inp-roster-names", "inp-roster-surnames"];
  const lines = text => text.replace(/\r\n?/g, "\n").split("\n");

  /** Presents independent paste columns without changing the stored student schema. */
  class RosterTable {
    constructor(document) {
      this.fields = FIELD_IDS.map(id => document.getElementById(id));
      this.fields.forEach((field, column) => {
        field.addEventListener("paste", event => this.paste(event, column));
        field.addEventListener("scroll", () => {
          this.fields.forEach(other => { other.scrollTop = field.scrollTop; });
        });
      });
    }

    /** Keeps blank cells aligned and leading zeroes intact for existing validation. */
    read() {
      const columns = this.fields.map(field => lines(field.value));
      return Array.from({ length: Math.max(...columns.map(column => column.length)) }, (_, row) =>
        columns.map(column => column[row] || "").join("\t")
      ).join("\n");
    }

    clear() {
      this.fields.forEach(field => { field.value = ""; field.scrollTop = 0; });
    }

    /** Validates file imports before replacing any unsaved table values. */
    load(text) {
      const result = root.StudentNumbers.parse(text);
      if (!result.ok) return result;
      const rows = result.students.map(student => {
        const parts = student.name.split(" ");
        const surname = parts.length > 1 ? parts.pop() : "";
        return [student.no, parts.join(" "), surname];
      });
      this.fields.forEach((field, column) => { field.value = rows.map(row => row[column]).join("\n"); });
      return { ok: true };
    }

    /** Distributes spreadsheet cells starting at the selected row and column. */
    paste(event, column) {
      const text = event.clipboardData.getData("text/plain");
      if (!text.includes("\t")) return;
      event.preventDefault();
      const field = this.fields[column];
      const startRow = lines(field.value.slice(0, field.selectionStart)).length - 1;
      const rows = lines(text.replace(/\r?\n$/, "")).map(row => row.split("\t"));
      if (rows.some(row => row.length > this.fields.length - column)) {
        root.alert(root.PortalLanguage?.text("En fazla üç sütun yapıştırınız: numara, isim, soyisim.") || "En fazla üç sütun yapıştırınız: numara, isim, soyisim.");
        return;
      }
      this.fields.slice(column).forEach((target, offset) => {
        const values = lines(target.value);
        rows.forEach((row, index) => {
          if (offset < row.length) values[startRow + index] = row[offset];
        });
        target.value = Array.from(values, value => value || "").join("\n");
      });
    }
  }

  root.RosterTable = RosterTable;
  if (typeof module !== "undefined") module.exports = { RosterTable };
})(typeof window !== "undefined" ? window : globalThis);
;

/* registered-roster.js */
(function (root) {
  const COLUMNS = ["Numara", "İsim", "Soyisim"];
  const keyOf = student => student.email || student.no;

  /** Splits legacy full names for display only; stored names remain unchanged. */
  function displayColumns(student) {
    const parts = String(student.name || "").trim().split(/\s+/);
    const surname = parts.length > 1 ? parts.pop() : "";
    return [student.no || "", parts.join(" "), surname];
  }

  /** Renders private roster actions using injected storage and clipboard dependencies. */
  class RegisteredRoster {
    constructor({ document, students, remove, reset, clipboard, confirm, notify, changed, text }) {
      Object.assign(this, { document, students, remove, reset, clipboard, confirm, notify, changed, text });
      this.selected = new Set();
      this.busy = false;
      this.container = document.getElementById("roster-items-container");
      this.feedback = document.getElementById("roster-list-feedback");
      document.getElementById("btn-roster-delete-selected").onclick = () => this.delete(this.students().filter(student => this.selected.has(keyOf(student))));
      document.getElementById("btn-roster-delete-all").onclick = () => this.delete(this.students());
      document.querySelectorAll("[data-language-toggle]").forEach(button => button.addEventListener("click", () => this.render()));
    }

    element(tag, text, className) {
      const element = this.document.createElement(tag);
      if (text) element.textContent = text;
      if (className) element.className = className;
      return element;
    }

    button(label, action) {
      const button = this.element("button", this.text(label), "btn-clear-rating");
      button.type = "button";
      button.disabled = this.busy;
      button.onclick = action;
      return button;
    }

    render() {
      const students = this.students();
      const current = new Set(students.map(keyOf));
      this.selected = new Set([...this.selected].filter(key => current.has(key)));
      this.document.getElementById("roster-count-badge").textContent = String(students.length);
      this.container.replaceChildren();
      const table = this.element("table", "", "registered-roster-table");
      table.setAttribute("aria-label", this.text("Kayıtlı Öğrenciler"));
      table.append(this.header(students));
      const body = this.element("tbody");
      students.forEach(student => body.append(this.row(student)));
      if (!students.length) {
        const cell = this.element("td", this.text("Henüz kayıtlı öğrenci bulunmuyor."));
        cell.colSpan = 5;
        const row = this.element("tr"); row.append(cell); body.append(row);
      }
      table.append(body); this.container.append(table); this.updateSelection();
    }

    checkbox(label, checked, action) {
      const input = this.element("input");
      input.type = "checkbox"; input.checked = checked; input.disabled = this.busy;
      input.setAttribute("aria-label", this.text(label)); input.onchange = action;
      return input;
    }

    header(students) {
      const head = this.element("thead"), row = this.element("tr"), select = this.element("th");
      this.selectAll = this.checkbox("Tüm öğrencileri seç", false, () => {
        this.selected = new Set(this.selectAll.checked ? students.map(keyOf) : []);
        this.render();
      });
      select.append(this.selectAll); row.append(select);
      COLUMNS.forEach((label, column) => {
        const cell = this.element("th"); cell.scope = "col";
        cell.append(this.element("span", this.text(label)));
        const copy = this.button("Kopyala", () => this.copy(column));
        copy.setAttribute("aria-label", this.text(`${label} sütununu kopyala`));
        copy.disabled = this.busy || !students.length; cell.append(copy); row.append(cell);
      });
      row.append(this.element("th", this.text("İşlemler"))); head.append(row); return head;
    }

    row(student) {
      const row = this.element("tr"), select = this.element("td"), key = keyOf(student);
      const checkbox = this.checkbox("Öğrenciyi seç", this.selected.has(key), event => {
        if (event.target.checked) this.selected.add(key); else this.selected.delete(key);
        this.updateSelection();
      });
      checkbox.setAttribute("aria-label", `${this.text("Öğrenciyi seç")} ${student.no || student.email}`);
      select.append(checkbox);
      row.append(select);
      displayColumns(student).forEach(value => {
        const cell = this.element("td", value); cell.setAttribute("data-roster-value", ""); row.append(cell);
      });
      const actions = this.element("td", "", "registered-roster-actions");
      if (student.email) {
        const email = this.element("small", student.email); email.setAttribute("data-roster-value", ""); actions.append(email);
      }
      if (!student.enabled) actions.append(this.element("small", this.text("Engelli")));
      if (!student.email) actions.append(this.button("Hesap Bağını Sıfırla", () => this.resetStudent(student.no)));
      actions.append(this.button("Sil", () => this.delete([student]))); row.append(actions); return row;
    }

    updateSelection() {
      const count = this.students().length;
      this.selectAll.checked = count > 0 && this.selected.size === count;
      this.selectAll.indeterminate = this.selected.size > 0 && this.selected.size < count;
      this.selectAll.disabled = this.busy || !count;
      this.document.getElementById("btn-roster-delete-selected").disabled = this.busy || !this.selected.size;
      this.document.getElementById("btn-roster-delete-all").disabled = this.busy || !count;
      this.document.getElementById("roster-selected-count").textContent = String(this.selected.size);
    }

    /** Copies exactly one displayed column, retaining blank cells and leading zeroes. */
    async copy(column) {
      try {
        await this.clipboard.writeText(this.students().map(student => displayColumns(student)[column]).join("\n"));
        this.feedback.textContent = this.text("Sütun kopyalandı.");
      } catch { this.feedback.textContent = this.text("Kopyalanamadı. Sütundaki metni seçip kopyalayınız."); }
    }

    async delete(students) {
      if (this.busy || !students.length) return;
      const keys = students.map(keyOf);
      const message = `${this.text("Silinecek öğrenci sayısı:")} ${keys.length}. ${this.text("Bu öğrencilerin ders erişimi kaldırılacak. Devam edilsin mi?")}`;
      if (!this.confirm(message)) return;
      this.busy = true; this.feedback.textContent = this.text("Liste güncelleniyor…"); this.render();
      try {
        const result = await this.remove(keys);
        this.feedback.textContent = result.ok ? this.text("Öğrenci kayıtları silindi.") : `${result.error}${result.removed ? ` (${this.text("Silinen kayıt sayısı:")} ${result.removed})` : ""}`;
        if (!result.ok) this.notify(result.error);
      } finally { this.busy = false; this.render(); this.changed(); }
    }

    async resetStudent(no) {
      if (this.busy || !this.confirm(this.text("Bu numaranın mevcut hesap bağlantısı kaldırılacak; öğrenci yeniden kayıt yapabilecek. Devam edilsin mi?"))) return;
      this.busy = true; this.render();
      try { const result = await this.reset(no); if (!result.ok) this.notify(result.error); }
      finally { this.busy = false; this.render(); }
    }
  }

  root.RegisteredRoster = RegisteredRoster;
  if (typeof module !== "undefined") module.exports = { RegisteredRoster, displayColumns };
})(typeof window !== "undefined" ? window : globalThis);
;

